import { execFileSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import fs from "node:fs";
import { isRecord } from "@openclaw/normalization-core/record-coerce";
import { expect, it } from "vitest";
import { prepareAgentAuthProfileRowsRead, loadPersistedAuthProfileStoreFromRows } from "../agents/auth-profiles/sqlite-read.js";
import { saveAuthProfileStore } from "../agents/auth-profiles/store-runtime.js";
import { installGatewayDatabaseEngine } from "../gateway/server-database-engine.js";
import { createAgentDatabaseInspectionRefusal, preparePendingAgentDatabase, recordAgentDatabaseAdmissions } from "../state/agent-database-admission.js";
import { openOpenClawAgentDatabase } from "../state/openclaw-agent-db.js";
import { prepareOpenClawAgentDatabaseExecution } from "../state/openclaw-agent-execution.js";
import { openOpenClawStateDatabase } from "../state/openclaw-state-db.js";
import { beginAgentDeletionJournal, readAgentDeletionJournal } from "../test-utils/agent-deletion-journal.js";
import { withOpenClawTestState } from "../test-utils/openclaw-test-state.js";
import { withEngineStoreAdmission } from "./database-engine/admission-scope.js";
import { resetDatabaseEngineSelectionForTest } from "./database-engine/context.test-support.js";
import { isPostgresSqlConnection } from "./sql-connection.js";
import * as admissionModule from "./sqlite-worker-operation-admission.js";
import { sqliteWorkerOwnerProbe } from "./sqlite-worker-owner-probe.test-support.js";
import { getWorkerMessageMetrics } from "./worker-message-metrics.js";

const connection = process.env.OPENCLAW_REAL_AUTH_PROOF_DSN;
const head = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
const results: unknown[] = [];
const cases = process.env.OPENCLAW_REAL_AUTH_BASE_CONTROL === "1" ? ["empty-journal"] as const : ["empty-journal", "deletion-after-open"] as const;
const batchCount = () => getWorkerMessageMetrics().find((metric) => metric.kind === "authority" && metric.direction === "from_worker")?.messages ?? 0;

it.skipIf(!connection).each(cases)("real PostgreSQL credential reader: %s", async (scenario) => {
  const events: string[] = [];
  let fact: boolean | null = null;
  let received = 0;
  let error: unknown;
  let credentialMatches = false;
  let returnedProfiles = 0;
  let globalEngine = "unknown";
  let agentEngine = "unknown";
  let journalAfter = "unknown";
  let transferRequests = 0;
  try {
    await withOpenClawTestState({ scenario: "minimal" }, async (state) => {
      await state.writeConfig({ database: { engine: "sqlite", families: { agent: { engine: "postgres" } }, postgres: { connection: connection!, schemaPrefix: `auth_proof_${randomUUID().slice(0, 8)}` } } });
      resetDatabaseEngineSelectionForTest();
      await installGatewayDatabaseEngine();
      const options = { agentId: "worker", env: state.env };
      const database = withEngineStoreAdmission(() => openOpenClawAgentDatabase(options));
      agentEngine = isPostgresSqlConnection(database.db) ? "postgres" : "sqlite";
      globalEngine = isPostgresSqlConnection(openOpenClawStateDatabase({ env: state.env }).db) ? "postgres" : "sqlite";
      const syntheticCredential = `synthetic-proof-${randomUUID()}`;
      withEngineStoreAdmission(() => saveAuthProfileStore({ version: 1, profiles: { "openai:proof": { type: "api_key", provider: "openai", key: syntheticCredential } } }, state.agentDir("worker")));
      events.push("canonical-credential-write-committed");
      expect(readAgentDeletionJournal("worker", { env: state.env })).toBeUndefined();
      events.push("global-journal-empty");
      await prepareOpenClawAgentDatabaseExecution(options, () => {});
      events.push("native-agent-open-completed");
      const refusal = createAgentDatabaseInspectionRefusal({ agentId: "worker", paths: [database.path], pending: true, reason: "real reader proof startup" });
      recordAgentDatabaseAdmissions([refusal], { env: state.env, source: "startup" });
      const reader = prepareAgentAuthProfileRowsRead({ databasePath: database.path, agentId: "worker", env: state.env, source: "canonical" });
      const observer = sqliteWorkerOwnerProbe.admission(admissionModule, (request, grant, admit) => {
        if (request.stage === "prepare" && isRecord(request.facts) && request.facts.kind === "auth-store-read") {
          transferRequests++;
          fact = typeof request.facts.agentDeletionJournalPresent === "boolean" ? request.facts.agentDeletionJournalPresent : null;
          events.push("auth-transfer-admission-requested");
          if (scenario === "deletion-after-open") {
            // Real native journal transaction plus its normal post-commit preparation invalidation.
            // The observer only controls timing; the original admission and grant stay unchanged.
            beginAgentDeletionJournal({ agentId: "worker", operationId: randomUUID(), agentDir: state.agentDir("worker"), workspaceDir: state.workspaceDir, sessionsDir: state.sessionsDir("worker"), databasePaths: [database.path], deleteFiles: false }, { env: state.env });
            events.push("native-deletion-journal-committed-before-admission");
          }
        }
        const isAuthTransfer = request.stage === "prepare" && isRecord(request.facts) && request.facts.kind === "auth-store-read";
        const batchesBeforeAdmission = batchCount();
        try {
          admit(request, grant);
          if (request.stage === "prepare" && isRecord(request.facts) && request.facts.kind === "auth-store-read") events.push("original-admission-accepted-and-rows-consumed");
        } catch (caught) {
          events.push("original-admission-refused");
          throw caught;
        } finally {
          if (isAuthTransfer) received += batchCount() - batchesBeforeAdmission;
        }
      });
      try {
        await preparePendingAgentDatabase(refusal, { env: state.env, assertCurrent() {} }, async () => {
          const rows = await reader.read();
          const store = loadPersistedAuthProfileStoreFromRows(rows, database.path);
          returnedProfiles = Object.keys(store?.profiles ?? {}).length;
          const profile = store?.profiles["openai:proof"];
          credentialMatches = profile?.type === "api_key" && profile.key === syntheticCredential;
          events.push("real-reader-returned-decoded-credential");
        });
      } catch (caught) {
        error = caught;
      } finally {
        observer.mockRestore();
        await reader.dispose();
        journalAfter = readAgentDeletionJournal("worker", { env: state.env }) ? "pending" : "absent";
        recordAgentDatabaseAdmissions([], { env: state.env, source: "startup" });
      }
    });
  } finally {
    resetDatabaseEngineSelectionForTest();
    const errorMessage = error instanceof Error ? error.message : error ? "non-Error refusal" : null;
    const safeError = errorMessage?.includes("deleted during startup inspection") ? "Agent worker was deleted during startup inspection" : errorMessage?.includes("admission changed") ? "Agent database admission changed during preparation" : errorMessage ? "native admission refused (see private local test log)" : null;
    results.push({ scenario, globalEngine, agentEngine, journalAfter, transferRequests, publishedJournalFact: fact, authorityFieldBatchesConsumed: received, returnedProfiles, credentialMatches, outcome: error ? "refused" : "adopted", error: safeError, events });
    if (process.env.OPENCLAW_REAL_AUTH_PROOF_OUTPUT) fs.writeFileSync(process.env.OPENCLAW_REAL_AUTH_PROOF_OUTPUT, JSON.stringify({ head, results }, null, 2));
  }
  expect({ agentEngine, globalEngine }).toEqual({ agentEngine: "postgres", globalEngine: "sqlite" });
  expect(transferRequests).toBe(1);
  if (scenario === "empty-journal") {
    if (error) throw error;
    expect({ fact, credentialMatches, returnedProfiles, journalAfter }).toEqual({ fact: false, credentialMatches: true, returnedProfiles: 1, journalAfter: "absent" });
    expect(received).toBeGreaterThan(0);
  } else {
    expect(error).toBeInstanceOf(Error);
    expect({ received, returnedProfiles, credentialMatches, journalAfter }).toEqual({ received: 0, returnedProfiles: 0, credentialMatches: false, journalAfter: "pending" });
  }
}, 120_000);

