const resolve = backend.resolveExecutionArgs;
if (!normalize || !resolve) {
  throw new Error("Anthropic CLI backend is missing a production resolver");
}

const fullExec = { tools: { exec: { mode: "full" } } };
const askExec = { tools: { exec: { mode: "ask" } } };
const normalizeForPolicy = (config: typeof fullExec) =>
  normalize(backend.config, { backendId: "claude-cli", agentId: "main", config } as never);
const resolveFor = (
  config: typeof fullExec,
  baseArgs: readonly string[],
  options: { useResume: boolean; controlOperation?: "compact" },
) =>
  resolve(
    {
      workspaceDir: process.cwd(),
      provider: "claude-cli",
    agentId: "main",
      modelId: "claude-opus-4-8",
      config,
      executionMode: "agent",
      ...options,
      baseArgs,
    } as never,
  );

const full = normalizeForPolicy(fullExec);
const ask = normalizeForPolicy(askExec);
const explicit = normalize(backend.config, {
  backendId: "claude-cli",
  agentId: "main",
  config: fullExec,
} as never);
const resumedExplicitArgs = [
  ...(explicit.resumeArgs ?? []),
  "--permission-mode",
  "acceptEdits",
];
const results = {
  normalFull: resolveFor(fullExec, full.args ?? [], { useResume: false }),
  compactFull: resolveFor(fullExec, full.resumeArgs ?? [], {
    useResume: true,
    controlOperation: "compact",
  }),
  compactAsk: resolveFor(askExec, ask.resumeArgs ?? [], {
    useResume: true,
    controlOperation: "compact",
  }),
  compactExplicit: resolveFor(fullExec, resumedExplicitArgs, {
    useResume: true,
    controlOperation: "compact",
  }),
};

